/* Passage-specific planning, briefing and forecast helpers. */
const currentSettingsKey='coastal-current-settings-v1';
let currentTimer,weatherSequence=0;
function saveCurrentSettings(){try{let x={};document.querySelectorAll('#form input[id],#form select[id]').forEach(e=>{if(e.checkValidity())x[e.id]=e.type==='checkbox'?e.checked:e.value;});localStorage.setItem(currentSettingsKey,JSON.stringify(x));}catch(e){}}
function restoreCurrentSettings(){try{const x=JSON.parse(localStorage.getItem(currentSettingsKey)||'{}');document.querySelectorAll('#form input[id],#form select[id]').forEach(e=>{if(!(e.id in x))return;let old=e.type==='checkbox'?e.checked:e.value;if(e.type==='checkbox')e.checked=!!x[e.id];else {e.value=x[e.id];if(!e.checkValidity()||(e.tagName==='SELECT'&&!e.value))e.value=old;}});}catch(e){}}
function scheduleCurrentUpdate(e){saveCurrentSettings();clearTimeout(currentTimer);if(!$('form').checkValidity())return;if(e.target.id==='uncertainty'&&trip){renderCurrentExtras();return;}const run=()=>{if($('run').disabled){currentTimer=setTimeout(run,300);return;}calculate().catch(()=>{});};currentTimer=setTimeout(run,500);}
function currentEligible(q){if($('arriveBy').checked){if(!$('arrivalDate').value||!$('arrivalTime').value)return false;try{if(q.end>eastern($('arrivalDate').value,$('arrivalTime').value))return false;}catch(e){return false;}}if($('daylightOnly').checked){for(let i=0;i<q.track.length;i+=10){const p=q.track[i];if(!NJPlanning.daylight(p.t,p.lat,p.lon))return false;}const p=q.track.at(-1);if(!NJPlanning.daylight(p.t,p.lat,p.lon))return false;}return true;}
function currentPoints(){const priority=new Set(['DEB2113','DEB2111','DEB2110','ACT4206','ACT4121','DEB2104','ACT4046','NYH1901','n03020','NYH1924','LIS1038','LIS1036','LIS1032','LIS1027','LIS1017','LIS1001','ACT2381','ACT1861','ACT1841','ACT1766','ACT1726','ACT1686']);let anchors=r.anchors.filter(a=>a.at>=0&&a.at<=r.total&&priority.has(a.station.id)).sort((a,b)=>a.at-b.at),out=[];for(const a of anchors){if(out.some(x=>x.station.id===a.station.id))continue;out.push(a);}if(!out.length){let nearby=r.anchors.filter(a=>a.at>=0&&a.at<=r.total).sort((a,b)=>a.at-b.at);for(const a of nearby)if(!out.some(x=>Math.abs(x.at-a.at)<8))out.push(a);}return out;}
function currentText(q){return q.mode==='unmodeled'?'Current not modeled':`${q.current.toFixed(1)} kt toward ${Math.round(q.dir)}° true · ${Math.abs(q.along).toFixed(1)} kt ${q.along>=0?'following':'opposing'}`;}
function renderCurrentExtras(){if(!trip)return;const selected=trip,points=currentPoints(),margin=+$('uncertainty').value;let entries=points.map(a=>{let t=P.atDistance(selected,a.at),q=P.sample(r,data,a.at,t,selected.speed),early=null,late=null;if(margin){try{early=P.sample(r,data,a.at,t-margin*60000,selected.speed);late=P.sample(r,data,a.at,t+margin*60000,selected.speed);}catch(e){}}return {a,t,q,early,late};});
 $('currentCritical').innerHTML=entries.length?'<div class="tableWrap"><table><thead><tr><th>Location</th><th>Expected arrival</th><th>Current along course</th><th>Early / late</th></tr></thead><tbody>'+entries.map((x,i)=>`<tr class="stationRowsLink" tabindex="0" data-current-index="${i}"><td>${x.a.station.name}</td><td>${fmt(x.t)}</td><td>${currentText(x.q)}</td><td>${margin?(x.early&&x.late?`${currentText(x.early)} / ${currentText(x.late)}`:'Prediction unavailable'):'Off'}</td></tr>`).join('')+'</tbody></table></div><p class="formHint">Early / late samples the predicted current at fixed location and shifted arrival time; it does not recalculate the full trip.</p>':'No modeled current stations on this passage.';
 $('currentCritical').querySelectorAll('[data-current-index]').forEach(row=>{const act=()=>{let e=entries[+row.dataset.currentIndex];inspect(e.a.at);if(map)map.panTo([e.q.lat,e.q.lon]);};row.onclick=act;row.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();act();}};});
 const delta=Math.round((selected.hours-r.total/selected.speed)*60),night=selected.track.some((q,i)=>i%10===0&&!NJPlanning.daylight(q.t,q.lat,q.lon));
 $('briefing').innerHTML=`<h3>${r.p[0].name} → ${r.p.at(-1).name}</h3><p>Depart ${fmt(selected.start)} · Arrive ${fmt(selected.end)}<br>${r.total.toFixed(1)} nm · ${duration(selected.hours)} underway · ${selected.speed} kt through water<br>${Math.abs(delta)} minutes ${delta<=0?'faster':'slower'} than without current · ${night?'Nighttime portions expected':'Daylight along sampled passage'}.</p>${r.unmodeledDistance?`<p>${r.unmodeledDistance.toFixed(1)} nm has no modeled current correction.</p>`:''}<h4>Critical current locations</h4><ul>${entries.map(x=>`<li>${x.a.station.name} · ${fmt(x.t)} · ${currentText(x.q)}${margin&&x.early&&x.late?` · ${margin} min early: ${currentText(x.early)}; ${margin} min late: ${currentText(x.late)}`:''}</li>`).join('')||'<li>No modeled current locations.</li>'}</ul><h4>Waypoint arrivals</h4><ul>${selected.arrivals.map((q,i)=>r.p[i].selectable!==false?`<li>${r.p[i].name} · ${fmt(q.t)} · ${currentText(q)} · ${q.sog.toFixed(1)} kt over ground</li>`:'').join('')}</ul><h4>Weather along the passage</h4><p id="currentWeather">Checking forecasts at estimated passage times…</p><p>Forecasts and currents are estimates; confirm updated marine forecasts and navigation information before departure.</p>`;
 updateCurrentWeather(selected,r);
}
async function updateCurrentWeather(selected,route){const seq=++weatherSequence;const box=$('currentWeather');const count=Math.min(12,Math.max(2,Math.ceil(route.total/35)+1)),samples=[];for(let i=0;i<count;i++){const s=route.total*i/(count-1),t=P.atDistance(selected,s),q=P.sample(route,data,s,t,selected.speed);const closest=route.p.reduce((a,b)=>((a.lat-q.lat)**2+(a.lon-q.lon)**2)<((b.lat-q.lat)**2+(b.lon-q.lon)**2)?a:b);samples.push({s,t,lat:q.lat,lon:q.lon,name:closest.name});}
 const get=async x=>{let common={latitude:x.lat.toFixed(3),longitude:x.lon.toFixed(3),timezone:'GMT',forecast_days:'7'};let air=new URLSearchParams({...common,hourly:'temperature_2m,weather_code,precipitation_probability,wind_speed_10m,wind_gusts_10m',temperature_unit:'fahrenheit',wind_speed_unit:'kn'}),sea=new URLSearchParams({...common,hourly:'wave_height',length_unit:'imperial'});let results=await Promise.allSettled([fetch('https://api.open-meteo.com/v1/forecast?'+air).then(z=>{if(!z.ok)throw Error();return z.json();}),fetch('https://marine-api.open-meteo.com/v1/marine?'+sea).then(z=>{if(!z.ok)throw Error();return z.json();})]);const select=v=>{if(v.status!=='fulfilled'||!v.value.hourly?.time)return null;let h=v.value.hourly,ix=h.time.findIndex(t=>Math.abs(Date.parse(t+'Z')-x.t)<1800000);return ix<0?null:{h,ix};};return {x,air:select(results[0]),sea:select(results[1])};};
 let all=await Promise.all(samples.map(get));if(seq!==weatherSequence||trip!==selected||!box.isConnected)return;const available=all.filter(v=>v.air&&Number.isFinite(v.air.h.weather_code?.[v.air.ix])&&Number.isFinite(v.air.h.wind_speed_10m?.[v.air.ix]));if(!available.length){box.textContent='Forecast unavailable for the passage dates or locations. Check current local and marine forecasts.';return;}let notes=[];for(const {x,air,sea} of available){const {h,ix}=air,code=h.weather_code[ix],gust=h.wind_gusts_10m[ix],wind=h.wind_speed_10m[ix],prob=h.precipitation_probability[ix],wave=sea?.h.wave_height?.[sea.ix],items=[];if(code>=95)items.push('thunderstorms forecast');else if(code>=51&&code<=82)items.push('rain or showers forecast');if(Number.isFinite(prob)&&prob>=50)items.push(prob+'% precipitation chance');if(Number.isFinite(wind)&&wind>=20)items.push(Math.round(wind)+' kt wind');if(Number.isFinite(gust)&&gust>=25)items.push('gusts '+Math.round(gust)+' kt');if(Number.isFinite(wave)&&wave>=4)items.push('waves '+wave.toFixed(1)+' ft');if(items.length)notes.push(`${x.name} around ${fmt(x.t)}: ${items.join(', ')}`);}box.textContent=(notes.length?notes.join(' · '):'No notable conditions identified in the available forecasts at sampled locations and times.')+` Forecast coverage: ${available.length}/${samples.length} route samples; marine wave data ${all.filter(x=>x.sea&&Number.isFinite(x.sea.h.wave_height?.[x.sea.ix])).length}/${samples.length}. Open-Meteo hourly weather and marine forecasts; conditions between samples may differ.`;}
window.addEventListener('load',()=>{$('printBrief').onclick=()=>{document.body.classList.add('printBrief');window.print();};window.addEventListener('afterprint',()=>document.body.classList.remove('printBrief'));});
